async def create_itn_tasks(user, itn_list):
    leftover = []
    with open("itn_velocites.txt", "a") as f:
        tasks = [user.fetch_itn_info(itn) for itn in itn_list]
        for fetch_job in tqdm(asyncio.as_completed(tasks), total = len(tasks)):
            try:
                result = await fetch_job
                f.write(f"{result['data']['inventory']['itn']},{result['data']['inventory']['Product']['Velocity'].strip() or 'N'}\n")
            except ClientResponseError as err:
                f.write(f"{err.message[:10]},DEAD\n")
            except ItnTimeoutError as e:
                leftover.append(e.itn)
    return leftover

async def main():
    with open("itn_velocites.txt", "w") as f:
        pass
    user = await oms.authorize_access()
    results = await create_itn_tasks(user, ITNS.split())
    while results:
        results = await create_itn_tasks(user, results)

    await user.close_session()

if __name__ == "__main__":
    asyncio.run(main())
